export const jointAxisNames=['이동 X','이동 Y','이동 Z','회전 X','회전 Y','회전 Z'];
export const defaultJointDOFs=()=>jointAxisNames.map(()=>({mode:'locked',lower:-1,upper:1,motor:false,position:0,velocity:0,stiffness:100,damping:10,maxForce:0}));
export function validJointDOFs(rows){return Array.isArray(rows)&&rows.length===6&&rows.every((r,i)=>r&&['locked','limited','free'].includes(r.mode)&&typeof r.motor==='boolean'&&['lower','upper','position','velocity','stiffness','damping','maxForce'].every(k=>Number.isFinite(r[k])&&Math.abs(r[k])<=1000000)&&r.lower<=r.upper&&r.stiffness>=0&&r.damping>=0&&r.maxForce>=0&&!(r.mode==='locked'&&r.motor)&&(i<3||r.lower>=-180&&r.upper<=180&&Math.abs(r.position)<=180));}
export const jointLockedAxes=rows=>rows.reduce((mask,row,i)=>row.mode==='locked'?mask|1<<i:mask,0);
export function configureJointDOFs(joint,rows){const raw=joint.rawSet,handle=joint.handle;for(let axis=0;axis<6;axis++){const row=rows[axis],scale=axis>=3?Math.PI/180:1;if(row.mode==='limited')raw.jointSetLimits(handle,axis,-row.upper*scale,-row.lower*scale);if(row.motor&&row.mode!=='locked'){raw.jointConfigureMotorModel(handle,axis,1);raw.jointConfigureMotor(handle,axis,-row.position*scale,-row.velocity*scale,row.stiffness,row.damping);if(row.maxForce>0)raw.jointSetMotorMaxForce(handle,axis,row.maxForce);}}}
export function editJointDOFs(rows,input){const next=structuredClone(rows),index=Number(input.dataset.jointDofIndex),field=input.dataset.jointDofField;if(!Number.isInteger(index)||index<0||index>=6||!Object.hasOwn(next[index],field))throw Error('관절 축 설정을 확인하세요.');const row=next[index];row[field]=input.type==='checkbox'?input.checked:input.type==='number'?Number(input.value):input.value;if(field==='mode'&&row.mode==='locked')row.motor=false;if(field==='motor'&&row.motor&&row.mode==='locked')row.mode='free';return next;}
